package com.tduck.cloud.api.ai;
import com.tduck.cloud.form.assistant.*;import com.tduck.cloud.form.entity.*;import com.tduck.cloud.form.mapper.*;import com.tduck.cloud.form.service.UserFormVersionService;import com.tduck.cloud.form.analysis.AnalysisSnapshotService;import org.junit.Test;import java.util.*;import static com.tduck.cloud.form.analysis.AnalysisJson.*;import static org.junit.Assert.*;import static org.mockito.Mockito.*;
public class AssistantSemanticFallbackTest {
 @Test public void topicRecoveryCannotSilentlyDropAnExplicitStatusFilter(){AssistantTools tools=mock(AssistantTools.class);when(tools.call(eq("search_surveys"),any(),eq(22L))).thenReturn(map("kind","surveys","total",0,"surveys",Collections.emptyList()));AssistantTurnMapper turns=mock(AssistantTurnMapper.class);AssistantTurnEntity turn=new AssistantTurnEntity();turn.setId(UUID.randomUUID().toString());turn.setOwnerId(22L);turn.setState("READY");turn.setQuestion("查找收集中外卖那份问卷");Map<String,Object> args=map("query","点外卖","status",1);turn.setPlanJson(write(map("tool","search_surveys","arguments",args,"automatic",true,"stage",0)));when(turns.selectById(turn.getId())).thenReturn(turn);when(turns.update(any(),any())).thenReturn(1);new AssistantChatService(mock(AssistantConversationMapper.class),turns,mock(AssistantPlanner.class),tools).execute(turn.getId(),"search_surveys",args,22L);verify(tools,never()).relatedSurveys(any(),any());}
 @Test public void topicRankingIsNotDominatedByCommonUniversityWords(){List<Map<String,Object>> ranked=AssistantTools.rankTitles("帮我查看大学生点外卖那份问卷的情况",Arrays.asList(map("formKey","ai","title","大学生AI使用调查"),map("formKey","food","title","大学生外卖消费原因调查"),map("formKey","club","title","大学生社团参与意愿调查")),30);assertEquals("food",ranked.get(0).get("formKey"));}
 @org.junit.BeforeClass public static void metadata(){org.apache.ibatis.builder.MapperBuilderAssistant b=new org.apache.ibatis.builder.MapperBuilderAssistant(new com.baomidou.mybatisplus.core.MybatisConfiguration(),"semantic-fallback");b.setCurrentNamespace(AssistantTurnMapper.class.getName());com.baomidou.mybatisplus.core.metadata.TableInfoHelper.initTableInfo(b,AssistantTurnEntity.class);org.apache.ibatis.builder.MapperBuilderAssistant f=new org.apache.ibatis.builder.MapperBuilderAssistant(new com.baomidou.mybatisplus.core.MybatisConfiguration(),"semantic-forms");f.setCurrentNamespace(UserFormMapper.class.getName());com.baomidou.mybatisplus.core.metadata.TableInfoHelper.initTableInfo(f,UserFormEntity.class);}
 @Test public void aLiteralSearchMissMustStillTryOwnedTopicCandidates(){UserFormMapper forms=mock(UserFormMapper.class);UserFormEntity food=new UserFormEntity();food.setFormKey("food");food.setName("大学生外卖消费原因调查");food.setUserId(22L);when(forms.selectList(any())).thenReturn(Arrays.asList(food));AssistantTools tools=spy(new AssistantTools(forms,mock(UserFormDataMapper.class),mock(UserFormVersionService.class),mock(AnalysisSnapshotService.class),mock(AnalysisReportMapper.class)));doReturn(map("kind","surveys","total",0,"surveys",Collections.emptyList())).when(tools).call(eq("search_surveys"),any(),eq(22L));doReturn(food).when(tools).requireOwned("food",22L);AssistantTurnMapper turns=mock(AssistantTurnMapper.class);AssistantTurnEntity turn=new AssistantTurnEntity();turn.setId(UUID.randomUUID().toString());turn.setQuestion("帮我查看大学生点外卖那份问卷的情况");turn.setOwnerId(22L);turn.setState("READY");Map<String,Object> args=map("query","大学生点外卖");turn.setPlanJson(write(map("tool","search_surveys","arguments",args,"automatic",true,"stage",0)));when(turns.selectById(turn.getId())).thenReturn(turn);when(turns.update(any(),any())).thenReturn(1);AssistantPlanner planner=mock(AssistantPlanner.class);when(planner.chooseSurvey(any(),any())).thenReturn("food");Map<String,Object> result=new AssistantChatService(mock(AssistantConversationMapper.class),turns,planner,tools).execute(turn.getId(),"search_surveys",args,22L);assertEquals("surveys",result.get("kind"));verify(planner).chooseSurvey(eq(turn.getQuestion()),argThat(candidates->candidates.stream().anyMatch(row->"food".equals(row.get("formKey")))));verify(tools).requireOwned("food",22L);}
}
